def _with_new_languages():
    """Adds the languages from strings_more.py; Serbian is converted from Montenegrin (ekavian, Cyrillic)."""
    import os, re, sys
    here = os.path.dirname(os.path.abspath(__file__))
    sys.path[:0] = [here, os.path.join(here, "..", "..", "tools")]
    from strings_more import MORE
    from to_serbian import convert
    def serbian(v):
        keep = re.findall(r"\$\{\w+\}|\$\w+|¶", v)
        for i, k in enumerate(keep):
            v = v.replace(k, f"{{K{i}}}", 1)
        v = convert(v)
        for i, k in enumerate(keep):
            v = v.replace(f"{{K{i}}}", k, 1)
        return v
    MORE["Serbian"] = {k: (serbian(v) if k != "LANG_CODE" else "sr") for k, v in MORE["Montenegrin"].items()}
    for lid in ["Finnish", "Estonian", "Serbian", "Croatian", "Montenegrin", "Bosnian", "Bulgarian", "Russian", "Greek"]:
        L.append(lid)
        for key in T:
            T[key].append(MORE[lid][key].replace("¶", N))


if __name__ == "__main__":
    import os
    _with_new_languages()
    out = ["; generated by strings_src.py - edit that file, not this one"]
    for key, vals in T.items():
        assert len(vals) == len(L), (key, len(vals))
        for lid, v in zip(L, vals):
            v = v.replace('"', '$\\"')
            out.append(f'LangString {key} ${{LANG_{lid.upper()}}} "{v}"')
    open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "strings.nsh"), "w", encoding="utf-8-sig").write("\n".join(out) + "\n")
    print("strings.nsh:", len(T), "texts x", len(L), "languages")
